#!/usr/bin/env bash
set -euo pipefail
: "${FABRIC_CA_CLIENT_HOME:?Set to organization registrar MSP home}"
: "${CA_URL:?HTTPS CA URL}"
: "${CA_NAME:?CA name}"
: "${CA_TLS_ROOT:?TLS root PEM path}"
: "${ENROLLMENT_ID:?New enrollment ID}"
: "${IDENTITY_DID:?DID registered by organization}"
[[ "$CA_URL" == https://* ]] || exit 1
# Password is generated by the CA; transfer stdout directly to a restricted handoff file.
# Do not enable shell tracing or send command output to centralized logs.
fabric-ca-client register --url "$CA_URL" --caname "$CA_NAME" --tls.certfiles "$CA_TLS_ROOT" \
 --id.name "$ENROLLMENT_ID" --id.type client --id.maxenrollments 1 \
 --id.attrs "aegis.did=$IDENTITY_DID:ecert"
